\begin{proof}

Let $(G, w, k)$ be an instance of \dsce where $G$ is a planar graph. We assume that $G$ is clean, as we can safely remove all vertices and edges that are not part of any shortest cycle.
If the graph is empty, we return a trivial no-instance. Otherwise, $G$ is clean and non-empty, therefore by \Cref{lem:facial}, there is also an internal face $f$ whose frontier is a shortest cycle, in some fixed planar embedding of $G$. We consider another embedding of $G$ where $f$ is the outer face, and compute the LSCT $\cT(G)$ as described in the proof of \Cref{thm:mincycles-vd}.

We first bound the number of leaves in $\cT(G)$.
\begin{claim}
    \label{claim:T_ed_leaves}
    If $\cT(G)$ has at least $4k$ leaves, then $(G, w, k)$ is a yes-instance.
\end{claim}
\begin{claimproof}
    Consider the graph $G_F$, where the vertex set is the set of shortest cycles in $G$ that are found in the leaves of $\cT(G)$, and a pair of vertices is adjacent if and only if the respective cycles share edges. Since the shortest cycles in the leaves of $\cT(G)$ are frontiers of internal faces in the embedding of~$G$, $G_F$ is a subgraph of the dual graph $G^*$ of $G$, and is therefore planar. By~\Cref{obs:ind-planar}, a planar graph with at least $4k$ vertices has an independent set of size $k$. The vertices of this independent set in~$G_F$ correspond to $k$ edge-disjoint shortest cycles in $G$, which proves the claim.
\end{claimproof}

By \Cref{claim:T_ed_leaves}, if there are at least $4k$ leaves in $\cT(G)$, we stop and return a trivial yes-instance. Thus, in the following we assume that $\cT(G)$ has less than $4k$ leaves.

For a shortest cycle $C$ in $G$, we say that its
\emph{extension} is any shortest cycle $C'$ with $C <_e C'$, and we say that $C'$ is its
\emph{lowest extension} if $C'$ is an extension of $C$ and for every other extension~$C''$ of~$C$, it holds that~$C' \le C''$.
\begin{claim}\label{claim:extensions}
Every shortest cycle $C$ in $G$ that has at least one extension, has a unique lowest extension.
\end{claim}

\begin{claimproof}
    Observe that for any shortest cycles $C' \le C''$ in $G$, if $C <_e C'$, then~$C <_e C''$.
    Consider first extensions of $C$ that are cycles in $\cT(G)$.  By \Cref{lem:tree}, all cycles $C'$ of $\cT(G)$ with~$C \le C'$ form a rooted subpath in~$\cT(G)$; by the above, the set of extensions of $C$ in~$\cT(G)$ forms a rooted subpath of this path. If the subpath is empty, then the root cycle itself shares edges with~$C$, in which case $C$ has no extension. Otherwise, let $C^*$ be the lowest cycle on this subpath; for each other extension~$C'$ in~$\cT(G)$, $C^* \le C'$. If $C^*$ is a U-node, by \Cref{lem:unsplit-decomp}~$C \le C'$ for some $C' \in \cC_u(C^*)$, and for every other shortest cycle $C''$ in $G_{C^*}$ with~$C \le C''$, it holds that~$C'' \le C'$.
    Since~$C' \in \cT(G)$ is not an extension of~$C$, there are no other extensions in $G_{C^*}$ and~$C^*$ is indeed the unique lowest extension.

    Now, consider the case where~$C^*$ is an S-node. Let $s,t$ be the poles of $C^*$ and let~${\cP_s(C) = \{P_0, \ldots, P_\ell\}}$ be the inclusion-wise maximal family of $s$-$t$-paths in $G_{C'}$ as in the construction of $\cC_s(C^*)$. By \Cref{lem:split-decomp}, either there exists $C' \in \cC_s(C^*)$ such that $C \le C'$, or~$C = P_i \cup P_j$ for some~$i < j \in [\ell]_0$.
    In the latter case, observe that $i > 0$ and $j < \ell$ since~$C$ shares no edges with $C^*$, and all non-tree cycles in $G_{C^*}$ that are extensions of $C$ are of the form~$P_{i'} \cup P_{j'}$ for some $i' < i$ and $j < j' \le \ell$. Hence, in this case $P_{i - 1} \cup P_{j + 1}$ is the lowest extension of $P_i \cup P_j$.
    Otherwise, if $C \le C'$ for some $C' \in \cC_s(C^*)$, then $C'$ shares edges with~$C$ by the choice of $C^*$ as~$C' \in \cT(G)$. Let $h \in [\ell]$ be such that $C' = P_{h - 1} \cup P_h$, let $i$ be the smallest index in~$\{h - 1, h\}$ such that $P_i$ shares edges with $C$, and let $j$ be the largest. By the same argument as in the previous case, $P_{i - 1} \cup P_{j + 1}$ is the lowest extension of $C$.
\end{claimproof}

Due to \Cref{claim:extensions}, for every shortest cycle $C$ in $G$ with at least one extension, we denote by~$L(C)$, the unique lowest extension of $C$. 
We say that the \emph{extension chain} $\cU(C)$ of $C$ is the sequence~$C_0, C_1, \ldots, C_r$ of shortest cycles in $G$ such that $C_0 = C$, $C_i = L(C_{i - 1})$ for each $i \in [r]$, and the cycle $C_r$ has no extension. 
Notice that, given $\cT(G)$, $\cU(C)$ can be found in polynomial time by tracing the path from $C$ to the root in the tree.


We now construct the set of \emph{marked} cycles $\cC_M$, which is a subset of all shortest cycles of $G$. We start by describing the set of \emph{base} cycles $\cC_B \subseteq \cC_M$, which contains
\begin{itemize}
    \item every leaf cycle of $\cT(G)$,
    \item every $U$-node that has at least two children,
    \item every $S$-node together with the cycles $P_0\cup P_{\ell - 1}$ and $P_1 \cup P_\ell$, where $\{P_0, \ldots, P_\ell\} = \cP_s(C)$.
\end{itemize}
If there exists a cycle $C \in \cC_B$ with a large enough extension chain, i.e., with $|\cU(C)| \ge k$, we stop and return a trivial yes-instance.
This is safe, since by definition all of the cycles in $\cU(C)$ are edge-disjoint.
Otherwise, we define $\cC_M$ to be all cycles of $\cC_B$ together with their extension chains, plus the root of~$\cT(G)$ and the set of all non-tree cycles: $\cC_M = \{r\} \cup \cC_N \cup \bigcup_{C \in \cC_B} \cU(C)$, where $\cC_N$ denotes the set of all shortest cycles in $G$ that are not in $\cT(G)$. We first observe that~$\cC_M$ is closed under taking the lowest extension.

\begin{claim}\label{claim:cM_closed}
    For every cycle $C \in \cC_M$, its lowest extension $L(C)$ also belongs to $\cC_M$, if it exists.
\end{claim}
\begin{claimproof}
    For each $C \in \cC_B$, the statement is immediate for $C$ and all cycles in $\cU(C)$, since their lowest extensions are added to $\cU(C)$ exhaustively by the definition.

    It remains to consider non-tree cycles. 
    Let $C$ be an S-node in $\cT(G)$ with ${\cP_s(C) = \{P_0, \ldots, P_\ell\}}$ and consider a non-tree cycle $C' = P_i \cup P_j$ for some $i < j \in [\ell]_0$.
    By the proof of \Cref{claim:extensions}, if $i > 0$ and~$j < \ell$, the lowest extension of $C'$ is $P_{i - 1} \cup P_{j + 1}$, which is either another non-tree cycle or the S-node~$C$; both are part of $\cC_M$ by definition. Finally, if $i = 0$ we claim that~$L(C') = L(P_0 \cup P_{\ell - 1})$, where~$P_0 \cup P_{\ell - 1} \in \cC_B$ and $L(P_0 \cup P_{\ell - 1}) \in \cC_M$. This holds since both lowest extensions are above $C$, while the intersection between $C$ and $C'$ is $P_0$, which is the same as the intersection between $C$ and $P_0 \cup P_{\ell - 1}$.
    The argument for $j = \ell - 1$ and $L(C') = L(P_1 \cup P_\ell)$ is analogous.
\end{claimproof}

By construction, we have an upper-bound on the size of $\cC_M$, which we prove in the next claim.

\begin{claim}\label{claim:marked_size}
    The size of $\cC_M$ is $\OO(k^2)$.
\end{claim}
\begin{claimproof}
    We first bound the number of base cycles, i.e., the size of $\cC_B$. 
    Recall that we have already bounded the number of leaves in $\cT(G)$ by 
    $4k-1$. This also implies that the number of internal vertices of $\cT(G)$ that have at least two children is less than $4k$. Therefore, the total number of $U$-nodes and $S$-nodes in $\cC_B$ is less than $4k$. By definition, $\cC_B$ contains two additional cycles for each $S$-node; from the above, the number of such cycles is less than $8k$. The total size of $\cC_B$ is therefore less than $16k$.

    For every $C \in \cC_B$, the size of its extension chain $\cU(C)$ is at most $k - 1$. Thus, the cycles of~$\cC_B$ together with their extension chains amount to less than $16k^2$ cycles. In addition to these cycles, $\cC_M$ contains the root and the non-tree cycles $\cC_N$. By the above, we have less than $4k$ $S$-nodes, and in total they have less than $8k$ children. Since an $S$-node with $p$ children contains at most $p \cdot (p + 1) / 2$ non-tree cycles, there are at most $4k \cdot (8k + 1)$ non-tree cycles in $G$ in total. The size of $\cC_M$ can be therefore upper-bounded by $52 \cdot k^2 = \OO(k^2)$.
\end{claimproof}

We now show the main property of the set of marked cycles $\cC_M$, that no other cycles are needed in order to find a $\cT$-maximal solution.

\begin{claim} \label{claim:marked}
    For every $\cT$-maximal solution $\cC$, it holds that $\cC \subseteq \cC_M$.
\end{claim}
\begin{claimproof}
    Consider a $\cT$-maximal solution $\cC$, and assume by contradiction that it is not contained in $\cC_M$. Let $C$ be the minimal cycle in $\cC$ with respect to ($\le$) that is not in $\cC_M$. Since $\cC_M$ contains all leaves and internal vertices of $\cT(G)$ with at least two children and all non-tree shortest cycles of $G$, we have that $C$ is a U-node in $\cT(G)$ with exactly one child $C'$. If $C' \in \cC$, then $C' \in \cC_M$ by the choice of $C$; but then $C' <_e C$, and $C$ is the lowest extension of $C'$, which contradicts the assumption that $C \notin \cC_M$, since by \Cref{claim:cM_closed}, $\cC_M$ is closed under taking the lowest extension.

    Therefore, $C' \notin \cC$, and let $\cC' = \cC \cup \{C'\} \setminus \{C\}$ be a set of $k$ shortest cycles obtained from~$\cC$ by replacing $C$ with $C'$. Since $\cC$ is $\cT$-maximal, it cannot be that $\cC'$ is a solution, thus $C'$ must share edges with some other cycle $C'' \in \cC \setminus\{C\}$; this cycle must be contained in $G_C$, since otherwise it also shares edges with $C$. By the choice of $C$, $C''$ is in the set of marked cycles $\cC_M$. We claim that $C$ is then the lowest extension of $C''$, which again contradicts the assumption that $C \notin \cC_M$. Indeed, since both $C$ and~$C''$ are part of the solution $\cC$, and $C'' \le C$, we have that $C'' <_e C$. On the other hand, $C$ shares edges with $C'$, which is the only other maximal cycle in $G_C$ with respect to ($\le$). Thus, no other shortest cycle in $G_C$ is an extension of $C''$, and~$C = L(C'')$. This finishes the proof of the claim.
\end{claimproof}

For a set of cycles $\cC$ in $G$, let $\bigcup \cC$ be a shortcut for $\bigcup_{C \in \cC} C$, i.e., the graph obtained by taking the union of all cycles in $\cC$, which is a subgraph of $G$.
Let $H = \bigcup \cC_M$; in other words, $H$ is the subgraph of $G$ obtained by removing all vertices and edges that are not in any of the cycles in~$\cC_M$. Since $H$ is a subgraph of $G$, we treat the weight function $w$ as a weight function on edges of~$H$ as well.
From \Cref{claim:marked}, it follows immediately that $(G, w, k)$ is a yes-instance of \dsce if and only if $(H, w, k)$ is a yes-instance. Therefore, we focus on $(H, w, k)$ for the remainder of the proof.

Observe also that the LSCT $\cT(H)$ can be seen as the result of dissolving degree-$2$ nodes in~$\cT(G)$. Here, dissolving a degree-$2$ node means removing the node from the graph while making its neighbors adjacent. Indeed, by construction of $\cC_M$, the only shortest cycles in $G$ that are not necessarily in $\cC_M$ are $U$-nodes with exactly one child. Removing vertices and edges of such a cycle $C$ that are not part of~$\cC_M$ results in the child of $C$ being directly adjacent to the parent of $C$ in the new LSCT. Note that all leaves, $S$-nodes, $U$-nodes with at least two children and the root node are preserved between $\cT(G)$ and $\cT(H)$.

While $H$ is constructed from only $\OO(k^2)$ cycles of $G$, it is not necessarily a kernel yet, since the number of vertices involved in these cycles may be large.
We now argue that the number of vertices in~$H$ can be reduced by showing that only a few vertices in $H$ have degree more than $2$.
We identify the vertices of degree at least $3$ by following the LSCT $\cT(H)$.
For each $C \in \cT(H)$, we define the set of vertices $B(C) \subseteq V(H_C)$ as follows.
If $C$ is an $S$-node, then $B(C) = \{s, t\}$, where $s, t$ are the poles of $C$. If $C$ is a $U$-node, let $B(C)$ be the set of vertices of degree at least three in the graph $\bigcup \{C\} \cup \cC_u(C)$, i.e., we consider only the cycle $C$ and its children in $\cT(H)$.

\begin{claim}\label{claim:U_nodes_degree}
    For each $U$-node $C$ of $\cT(H)$ with $p$ children, the size of $B(C)$ is at most $p \cdot (p + 1)$.
\end{claim}
\begin{claimproof}
   The family $\{C\} \cup \cC_u(C)$ contains $p + 1$ cycles. By \Cref{lem:trivial}, every two of these cycles either touch or do not intersect. Therefore, for every two cycles $C_1$ and $C_2$ there are at most two vertices of degree at least $3$ in $C_1 \cup C_2$, which are the endpoints of the shared path $C_1 \cap C_2$. On the other hand, every vertex of degree at least three in  $\bigcup \cC_u(C) \cup \{C\}$ has two incident edges that belong to some distinct cycles $C_1, C_2 \in \{C\} \cup \cC_u(C)$, which means that this vertex has degree at least three also in~$C_1 \cup C_2$. Thus, the size of $B(C)$ is at most twice the number of pairs of cycles in $\{C\} \cup \cC_u(C)$, showing the claim.
\end{claimproof}

\begin{claim}\label{claim:high_degree}
    The number of vertices of degree at least three in $H$ is in $\OO(k^2)$.
\end{claim}
\begin{claimproof}
    Let $B = \bigcup_{C \in \cT(H)} B(C)$.
    Let $v$ be a vertex of degree at least $3$ in $H$, we claim that $B$ contains $v$. By definition, $B$ contains the poles of all splittable cycles, so it remains to consider the case where $v$ is not a pole of any splittable cycle.
    Since the degree of $v$ is at least three in $H$, there exist two distinct shortest cycles~$C_1$, $C_2$ in $H$ that contain distinct edges incident to $v$. Assume~$C_1$ is a non-tree cycle, then by \Cref{lem:tree}, (ii), there exist a splittable cycle $C \in \cT(H)$ with $\cP_s(C) = \{P_0, \ldots, P_\ell\}$ and~$C_1 = P_i \cup P_j$ for some $0 \le i < j \le \ell$. Since~$v$ is not a pole of $C$,~$v$ is an internal vertex of~$P_i$ or~$P_j$; in any case, there exists a cycle in~$\cC_s(C)$ that contains the same edges incident to~$v$ as~$C_1$, so~$C_1$ may be replaced by this cycle.
    Since an analogous argument can be applied to $C_2$, from now on we assume that both~$C_1$ and~$C_2$ are nodes of $\cT(H)$.

    Let $C_1$, $C_2$ be the closest pair of cycles with this property, where the distance is measured over the tree $\cT(H)$, and let $C_1$ be the highest node in $\cT(H)$ among $C_1$, $C_2$. We claim that either $C_1$ is the parent of $C_2$ in $\cT(H)$, or $C_1$ and $C_2$ have a common parent in $\cT(H)$. Assume the contrary, and consider two cases depending on the locations of $C_1$ and $C_2$ in $\cT(H)$.

    \noindent\textbf{Case 1} ($C_2 \le C_1$): Consider the parent $C$ of $C_2$ in $\cT(H)$, $C \le C_1$ and $C \ne C_1$. The cycle~$C$ contains~$v$, since otherwise $v$ is an inner vertex of $H_C$ and cannot be on the cycle $C_1$.
    If $C$ contains the same edges incident to $v$ as $C_2$, then $C_1$, $C$ fulfill the same property but are closer in $\cT(H)$ than $C_1$, $C_2$, which is a contradiction. Otherwise, $C$ contains an edge incident to $v$ that is not contained in $C_2$, and the pair~$(C, C_2)$ fulfills the property, leading to a contradiction.

    \noindent\textbf{Case 2} ($C_2 \nleq C_1$ and $C_1 \nleq C_2$): Let $C$ be the parent of $C_2$ in $\cT(H)$. By the assumption, $C$ is not the parent of $C_1$, and also $C_1 \nleq C$ since otherwise $C_1$ has lower depth in $\cT(H)$ than $C_2$. Similarly to the previous case, $C$ contains $v$, as otherwise $C_1$ and $C_2$ cannot share the vertex. Again, either $C$ contains the same edges incident to $v$ as $C_2$, or it contains an edge incident to~$v$ that is not part of $C_2$. Thus, either $C_1$ and $C$ or $C$ and $C_2$ fulfill the property while being closer in $\cT(H)$ than $C_1$ and $C_2$, which is a contradiction.

    We now have that either $C_1$ is the parent of $C_2$, or there is a cycle $C$ that is the parent of both $C_1$ and $C_2$ in $\cT(H)$.
    If $C_1$ is the parent of $C_2$, and $C_1$ is an $S$-node, then $v$ is a pole, which we assume is not the case; the same holds if $C$ is an $S$-node and $C_1, C_2 \in \cC_s(C)$. If $C_1$ is the parent of $C_2$ and $C_1$ is a $U$-node, then $C_1 \cup C_2$ is a subgraph of $\bigcup \cC_u(C_1) \cup \{C_1\}$, so $v \in B(C_1)$. By the same argument, if $C$ is a $U$-node and $C_1, C_2 \in \cC_u(C)$, then $v$ has degree at least three in~$C_1 \cup C_2$ and so in $\bigcup \cC_u(C) \cup \{C\}$, thus $v \in B(C)$.
    This concludes the proof that $B$ contains all vertices of degree at least $3$ in $H$.

    It remains to bound the number of elements in $B$. For each $C \in \cT(H)$ that is either an $S$-node or a $U$-node with one child, it holds that~$|B(C)| \le 2$.
    Since $|\cC_M| \in \OO(k^2)$, the total contribution of these nodes to $B$ is $\OO(k^2)$.
    Observe that $\cT(H)$ has at most $4k$ leaves, since the leaves of $\cT(H)$ and the leaves of $\cT(G)$ are the same.
    Therefore, the total number of children of all $U$-nodes with at least two children in $\cT(H)$ is at most $8k$. Since a $U$-node with $p$ children contributes at most $p \cdot (p + 1)$ vertices to $B$ by \Cref{claim:U_nodes_degree}, all $U$-nodes with at least two children contribute in total at most $8k \cdot (8k + 1) \in \OO(k^2)$ vertices to $B$. The total size of $B$ is therefore also $\OO(k^2)$.
\end{claimproof}

We now exhaustively apply the following reduction rules, in order to remove all degree-$2$ vertices in~$H$.
\begin{redrule}\label{redrule:dissolve}
If there is a vertex of degree $2$ in $H$, dissolve it: remove the vertex and add an edge between its former neighbors, such that the weight of the new edge is equal to the sum of weights of the two removed edges.
\end{redrule}
Note that \ref{redrule:dissolve} may create loops and parallel edges. Thus we allow for intermediate instances to be multigraphs. We introduce two more reduction rules so that the resulting instance is a simple graph.
\begin{redrule}\label{redrule:loops}
If there is a loop $e$ in $H$, remove it from the graph. If $w(e) = g(G)$, additionally decrease $k$ by $1$. If this increases the length of the shortest cycle, return a trivial no-instance unless $k$ becomes $0$, in which case return a trivial yes-instance.
\end{redrule}
\begin{redrule}\label{redrule:parallel}
If there are two parallel edges $e_1$ and $e_2$ in $H$, remove both and decrease~$k$ by $1$ if $w(e_1) + w(e_2) = g(G)$. If this increases the length of the shortest cycle, return a trivial no-instance unless $k$ becomes $0$, in which case return a trivial yes-instance. Otherwise, if~$w(e_1) + w(e_2) > g(G)$, then remove one of the parallel edges with the highest weight without changing $k$.
\end{redrule}

\begin{claim}\label{claim:redrules}
    \Cref{redrule:dissolve,redrule:loops,redrule:parallel} are safe.
\end{claim}
\begin{claimproof}
    First, for \Cref{redrule:dissolve}, observe that every cycle in $H$ either remains unchanged, or is replaced by a cycle that passes through the newly-created edge, while the length of the cycle and the set of remaining edges stays the same. Therefore, the length of all cycles is unchanged, any two cycles that were edge-disjoint stay edge-disjoint, and any two cycles that shared edges still share edges after applying the reduction rule.

    Second, consider a loop $e$ to which \Cref{redrule:loops} is applied. If $w(e) > g(G)$, no shortest cycle passes through~$e$, thus it can be safely removed. If $w(e) = g(G)$, the only shortest cycle passing through~$e$ is the one that contains the edge $e$ and nothing else, as only simple cycles are considered. Adding this cycle to the solution is safe as no other cycle in $H$ can share edges with it.

    Finally, let $e_1$, $e_2$ be the parallel edges in \Cref{redrule:parallel}, with the endpoints $u, v$. We start with the case $w(e_1) + w(e_2) = g(G)$. If $k = 1$, then the cycle $C$ containing $e_1$ and~$e_2$ is indeed a solution; if $k > 1$ and $g(H') > g(H)$, where $H' = H - e_1 - e_2$, then $(H, w, k)$ is a no-instance: Otherwise, each cycle in the solution must use a different edge in $\{e_1, e_2\}$, so $k = 2$, but then the remaining $u$-$v$-paths of the two cycles in $H'$ form a cycle of length~$g(G) = g(H)$ in~$H'$, contradicting $g(H) < g(H')$. Now, with $g(H') = g(H)$, we claim that a packing of $k$ edge-disjoint shortest cycles exist in~$H$ if and only if a packing of $k - 1$ edge-disjoint shortest cycles exists in~$H' = H$. The backward direction is clear, since the cycle~$C$ containing $e_1$ and~$e_2$ can be added to any packing in $H'$. In the forward direction, if the statement does not hold, then the solution in $H$ does not contain the cycle $C$, but contains at least one cycle with an edge in~$\{e_1, e_2\}$. If there is just one such cycle, then it can be replaced by $C$, so that the remaining~$k - 1$ cycles form a packing in $H$. If there are two cycles $C_1$ and $C_2$, containing $e_1$ and $e_2$ respectively, let $P_1$ be the $u$-$v$-path in $C_1$ other than $e_1$, and $P_2$ be the $u$-$v$-path in $C_2$ other than $e_2$. Since~$w(C_1) + w(C_2) = 2g(G)$ and~$w(e_1) + w(e_2) = g(G)$, it holds that~$w(P_1) + w(P_2) = g(G)$ and the cycle $C' = P_1 \cup P_2$ is also a shortest cycle.
    However, we can then replace $C_1$ and $C_2$ with~$C$ and $C'$ to get a packing of $k$ edge-disjoint shortest cycles in~$H$ that contains $C$.

    In the other case let without loss of generality be~$w(e_2) \geq w(e_1)$. If~${w(e_1) < w(e_2)}$, then no shortest cycle may pass through $e_2$, so removing the edge $e_2$ is safe. If~$w(e_1) = w(e_2) > g(G)/2$, then no shortest cycle can contain both $e_1$ and~$e_2$. Also, it cannot be that two edge-disjoint shortest cycles contain $e_1$ and~$e_2$, respectively, as then by joining~$C_1 - e_1$ and~$C_2 - e_2$ we get a cycle that is shorter than $g(G)$. Thus, in any solution at most one cycle passes through either $e_1$ or $e_2$. Thus, it is safe to remove $e_2$ since any such cycle may pass through $e_1$ instead.
\end{claimproof}

By applying \Cref{redrule:dissolve,redrule:loops,redrule:parallel} exhaustively, we obtain a simple graph $G'$ with the weight function~$w'$, and an integer $k' \le k$ such that $(G, w, k)$ is equivalent to $(G', w', k')$ (by \Cref{claim:redrules}). Moreover, $|V(G')| \in \OO(k^2)$, by \Cref{claim:high_degree} and since \Cref{redrule:dissolve} can no longer be applied. It remains to compress the weights, so that they can be represented by~$k^{\OO(1)}$ bits.
Let $n = |V(G')|$, $m = |E(G'|$, we have that $m \in \OO(k^4)$. We now interpret the weight function $w' : E(G') \to \mathbb{Z}$ as a vector in~$\mathbb{Z}^m$ by assigning an arbitrary numbering to the edges of $G'$, and invoke \Cref{prop:FT} with~$w'$ and $N = m + 1$ to obtain a compressed vector $\overline{w} \in \mathbb{Z}^m$. From \Cref{prop:FT}, we have that for any vector~$b \in \mathbb{Z}^m$ with~$||b||_1 \le m$, $\mathsf{sign}(w'\cdot b)=\mathsf{sign}(\overline{w}\cdot b)$. Interpreting the vector $\overline{w}$ as a weight function on $E(G')$, we obtain the instance $(G', \overline{w}, k')$ of \dsce. By \Cref{prop:FT}, ${||\overline{w}||_{\infty} \le 2^{4m^3} \cdot (m + 1)^{m (m + 2)} \in 2^{\OO(k^{12})}}$, therefore each entry of $\overline{w}$ can be represented by~$\OO(k^{12})$~bits. The bit size of~$(G', \overline{w}, k')$ is thus in~$\OO(k^{16})$.
It remains to verify that $(G', \overline{w}, k')$ is indeed equivalent to~$(G', w', k')$. We show that for every pair of cycles in $G'$, their weights compare in the same way before and after the weight compression.

\begin{claim}\label{claim:weight_compression}
    For every two cycles $C_1$, $C_2$ in $G'$, $w'(C_1)$ is smaller than (equal to/larger than)~$w'(C_2)$ if and only if $\overline{w}(C_1)$ is smaller than (equal to/larger than) $\overline{w}(C_2)$.
\end{claim}
\begin{claimproof}
    It suffices to show that $\mathsf{sign}(w'(C_1) - w'(C_2))=\mathsf{sign}(\overline{w}(C_1) - \overline{w}(C_2))$.
    For each cycle~$C_i$ with $i \in \{1, 2\}$, consider its characteristic vector~$a_i \in \{0, 1\}^m$, where the $j$-th coordinate is equal to~$1$ if and only if the $j$-th edge of $G'$ belongs to $C_i$. By definition, $w'(C_i) = w' \cdot a_i$ and $\overline{w}(C_i) = \overline{w} \cdot a_i$ for each~$i \in \{1, 2\}$. Let $b \in \{-1, 0, 1\}^m$ be the difference vector $a_1 - a_2$, then $w'(C_1) - w'(C_2) = w' \cdot b$ and~$\overline{w}(C_1) - \overline{w}(C_2) = \overline{w} \cdot b$. By construction, $||b||_1 \le m$, so \Cref{prop:FT} applies to the vector $b$, therefore
    $\mathsf{sign}(w'\cdot b)=\mathsf{sign}(\overline{w}\cdot b)$, which means that $\mathsf{sign}(w'(C_1) - w'(C_2))=\mathsf{sign}(\overline{w}(C_1) - \overline{w}(C_2))$.
\end{claimproof}

From \Cref{claim:weight_compression} we have that every shortest cycle in the instance $(G', \overline{w}, k')$ is a shortest cycle in $(G', w', k')$, and the other way around.
Therefore, the instances are equivalent with respect to the existence of a packing of $k$ edge-disjoint shortest cycles.
Since $(G', w', k')$ was previously shown to be equivalent to the original instance $(G, w, k)$ of \dsce, $(G', \overline{w}, k')$ is equivalent to $(G, w, k)$ as well, and, from the above, the bit-size of $(G', \overline{w}, k')$ is $\OO(k^{16})$. This completes the proof of the theorem.
\end{proof}
